// Products is the resolver for the products field.
func (r *queryResolver) Products(ctx context.Context) ([]*model.Product, error) {
	bizID := getOrCreateBusiness(ctx, r.Queries)
	dbProducts, err := r.Queries.GetProducts(ctx, bizID)
	if err != nil {
		return nil, err
	}

	var products []*model.Product
	for _, p := range dbProducts {
		sellingPrice := parseDecimalStr(p.SellingPrice.String)
		products = append(products, &model.Product{
			ID:           p.ID.String(),
			Name:         p.Name,
			Sku:          &p.Sku.String,
			Balance:      parseDecimalStr(p.Balance),
			SellingPrice: &sellingPrice,
		})
	}
	return products, nil
}

