// InventoryHistory is the resolver for the inventoryHistory field.
func (r *queryResolver) InventoryHistory(ctx context.Context, productID *string) ([]*model.InventoryMovement, error) {
	bizID := getOrCreateBusiness(ctx, r.Queries)

	var pID uuid.NullUUID
	if productID != nil {
		id, err := uuid.Parse(*productID)
		if err == nil {
			pID.UUID = id
			pID.Valid = true
		}
	}

	movements, err := r.Queries.GetInventoryMovements(ctx, db.GetInventoryMovementsParams{
		BusinessID: bizID,
		ProductID:  pID,
	})
	if err != nil {
		return nil, err
	}

	var res []*model.InventoryMovement
	for _, m := range movements {
		var notes *string
		if m.Notes.Valid {
			notes = &m.Notes.String
		}
		res = append(res, &model.InventoryMovement{
			ID:             m.ID.String(),
			Type:           model.MovementType(m.Type),
			QuantityChange: parseDecimalStr(m.QuantityChange),
			BalanceAfter:   parseDecimalStr(m.BalanceAfter),
			Notes:          notes,
			CreatedAt:      m.CreatedAt.Time,
		})
	}
	return res, nil
}

// Mutation returns MutationResolver implementation.
func (r *Resolver) Mutation() MutationResolver { return &mutationResolver{r} }

// Query returns QueryResolver implementation.
func (r *Resolver) Query() QueryResolver { return &queryResolver{r} }

type (
	mutationResolver struct{ *Resolver }
	queryResolver    struct{ *Resolver }
)
